events {
    worker_connections 1024;
}

http {
    server_tokens off;
    proxy_hide_header X-Powered-By;
    resolver 127.0.0.11 valid=10s ipv6=off;

    # Restrict CORS to known production origins — never echo $http_origin
    map $http_origin $cors_origin {
        default "";
        "https://wimsbfp.tech" $http_origin;
        "https://wims.bfp.gov.ph" $http_origin;
    }

    upstream backend_servers {
        zone backend_servers 64k;
        server backend:8000 resolve;
        keepalive 32;
    }

    upstream frontend_servers {
        zone frontend_servers 64k;
        server frontend:3000 resolve;
    }

    upstream keycloak_servers {
        zone keycloak_servers 64k;
        server keycloak:8080 resolve;
    }

    client_max_body_size 50M;

    # ---------- DoS hardening --------------------------------------------------
    # Slowloris: tear down slow-header / slow-body senders within 10 s.
    client_body_timeout   10s;
    client_header_timeout 10s;
    keepalive_timeout     65s;
    send_timeout          10s;

    # Trust the Docker bridge as the source of X-Forwarded-For. Nginx
    # resolves $remote_addr from the header instead of the socket IP so
    # per-IP rate-limit keys reflect the real client, not the container
    # bridge. The previous /12 (1,048,576 addrs) was 16x wider than
    # necessary and left X-Forwarded-For spoofing open on any other
    # endpoint that still reads $remote_addr (gap #14 followup, BLK-1).
    # Narrow the trusted-proxy range to the configured wims_internal bridge subnet.
    set_real_ip_from  172.18.0.0/24;   # wims_internal bridge subnet
    set_real_ip_from  127.0.0.1;
    real_ip_header    X-Forwarded-For;
    real_ip_recursive on;

    # Per-IP rate-limit zones — stored in 10 MB shared memory.
    # public_api:   tight limit for the unauthenticated zero-trust DMZ endpoint.
    # civilian_api: mid-tier limit for the civilian report form (higher blast radius).
    # general_api:  relaxed limit for all other backend routes.
    # Both public_api and civilian_api use $realip_remote_addr (TCP socket IP,
    # pre-real-IP-module) so the zone key cannot be rotated by spoofing XFF.
    limit_req_zone  $realip_remote_addr zone=public_api:10m    rate=10r/s;
    limit_req_zone  $realip_remote_addr zone=civilian_api:10m  rate=5r/s;
    limit_req_zone  $binary_remote_addr zone=general_api:10m   rate=30r/s;
    limit_req_zone  $binary_remote_addr zone=keycloak_api:10m   rate=10r/s;
    limit_conn_zone $binary_remote_addr zone=addr:10m;

    # POST-only rate limit for password-reset abuse protection.
    map $request_method $reset_post_only {
        POST    $realip_remote_addr;
        default "";
    }
    limit_req_zone  $reset_post_only zone=reset_credentials:10m rate=1r/m;

    # Return 429 (Too Many Requests) instead of the default 503.
    limit_req_status  429;
    limit_conn_status 429;
    # ---------------------------------------------------------------------------

    # ── Local dev: HTTP-only passthrough for localhost ────────────────────────
    # Serves the full stack over plain HTTP on local machines.
    # The HTTPS block only matches wimsbfp.tech so this block is a no-op on the
    # production VPS (Host header is never localhost there).
    server {
        listen 80;
        listen 8090;
        listen [::]:80;
        server_name localhost 127.0.0.1;

        location = /health {
            access_log off;
            default_type application/json;
            return 200 '{"status":"ok","via":"nginx-gateway"}\n';
        }

        location = /api/events/stream {
            proxy_pass http://backend_servers;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_buffering off;
            proxy_cache off;
            proxy_read_timeout 86400s;
            proxy_send_timeout 86400s;
            chunked_transfer_encoding off;
        }

        location /api/auth/ {
            proxy_pass http://frontend_servers;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
        }

        location /api/v1/public/ {
            limit_req  zone=public_api burst=5 nodelay;
            limit_conn addr 10;

            proxy_pass http://backend_servers;
            proxy_set_header Host $host;
            # Use the pre-real-IP-module socket address so the backend rate
            # limiter cannot be bypassed by a spoofed X-Forwarded-For header.
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $realip_remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_read_timeout 60s;
            proxy_send_timeout 60s;
            proxy_cookie_domain nginx-gateway $host;
            add_header Access-Control-Allow-Origin $http_origin always;
            add_header Access-Control-Allow-Credentials true always;
            add_header Access-Control-Allow-Methods 'GET, POST, PUT, DELETE, OPTIONS' always;
            add_header Access-Control-Allow-Headers 'Authorization, Content-Type, Cookie' always;
            add_header Access-Control-Expose-Headers "Retry-After" always;

            if ($request_method = 'OPTIONS') {
                add_header Access-Control-Allow-Origin $http_origin always;
                add_header Access-Control-Allow-Credentials true always;
                add_header Access-Control-Allow-Methods 'GET, POST, PUT, DELETE, OPTIONS' always;
                add_header Access-Control-Allow-Headers 'Authorization, Content-Type, Cookie' always;
                add_header Access-Control-Expose-Headers "Retry-After" always;
                add_header Content-Length 0;
                add_header Content-Type text/plain;
                return 204;
            }
        }

        location /api/civilian/ {
            limit_req  zone=civilian_api burst=10 nodelay;
            limit_conn addr 10;

            proxy_pass http://backend_servers;
            proxy_set_header Host $host;
            # Use the pre-real-IP-module socket address so the backend DB rate
            # limiter cannot be bypassed by a spoofed X-Forwarded-For header.
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $realip_remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_read_timeout 30s;
            proxy_send_timeout 30s;
            proxy_cookie_domain nginx-gateway $host;
            add_header Access-Control-Allow-Origin $http_origin always;
            add_header Access-Control-Allow-Credentials true always;
            add_header Access-Control-Allow-Methods 'GET, POST, PUT, DELETE, OPTIONS' always;
            add_header Access-Control-Allow-Headers 'Authorization, Content-Type, Cookie' always;
            add_header Access-Control-Expose-Headers "Retry-After" always;

            if ($request_method = 'OPTIONS') {
                add_header Access-Control-Allow-Origin $http_origin always;
                add_header Access-Control-Allow-Credentials true always;
                add_header Access-Control-Allow-Methods 'GET, POST, PUT, DELETE, OPTIONS' always;
                add_header Access-Control-Allow-Headers 'Authorization, Content-Type, Cookie' always;
                add_header Access-Control-Expose-Headers "Retry-After" always;
                add_header Content-Length 0;
                add_header Content-Type text/plain;
                return 204;
            }
        }

        location /api/ {
            limit_req  zone=general_api burst=50 nodelay;
            limit_conn addr 20;

            proxy_pass http://backend_servers;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_read_timeout 300s;
            proxy_send_timeout 300s;
            proxy_cookie_domain nginx-gateway $host;
            # dev-only: open CORS echo — intentionally permissive for local development;
            # must never ship to production (the HTTPS block uses an origin whitelist).
            add_header Access-Control-Allow-Origin $http_origin always;
            add_header Access-Control-Allow-Credentials true always;
            add_header Access-Control-Allow-Methods 'GET, POST, PUT, DELETE, OPTIONS' always;
            add_header Access-Control-Allow-Headers 'Authorization, Content-Type, Cookie' always;

            if ($request_method = 'OPTIONS') {
                add_header Access-Control-Allow-Origin $http_origin always;
                add_header Access-Control-Allow-Credentials true always;
                add_header Access-Control-Allow-Methods 'GET, POST, PUT, DELETE, OPTIONS' always;
                add_header Access-Control-Allow-Headers 'Authorization, Content-Type, Cookie' always;
                add_header Content-Length 0;
                add_header Content-Type text/plain;
                return 204;
            }
        }

        # POST-only rate limit for password reset abuse protection.
        location = /auth/realms/bfp/login-actions/reset-credentials {
            limit_req  zone=reset_credentials burst=2 nodelay;
            limit_conn addr 10;

            proxy_pass http://keycloak_servers/auth/realms/bfp/login-actions/reset-credentials;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Forwarded-Host $host;
            proxy_set_header X-Forwarded-Port $server_port;
        }

        location /auth/ {
            limit_req  zone=keycloak_api burst=20 nodelay;
            limit_conn addr 10;

            proxy_pass http://keycloak_servers/auth/;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Forwarded-Host $host;
            proxy_set_header X-Forwarded-Port $server_port;
        }

        # /metrics is an internal-only Prometheus scrape target (system
        # resource gauges, request/inference timings). Scrapers reach it
        # directly at backend:8000 over the compose network; it must never
        # be served through the public edge. Deny explicitly so a future
        # routing change can't expose it.
        location = /metrics {
            return 404;
        }

        location / {
            proxy_pass http://frontend_servers/;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
        }
    }

    # ── HTTP → HTTPS redirect ──────────────────────────────────────────────────
    server {
        listen 80;
        listen [::]:80;
        server_name wimsbfp.tech;

        location / {
            return 301 https://$host$request_uri;
        }
    }

    # ── TLS termination ───────────────────────────────────────────────────────
    server {
        listen 443 ssl;
        listen [::]:443 ssl;
        server_name wimsbfp.tech;

        ssl_certificate     /etc/letsencrypt/live/wimsbfp.tech/fullchain.pem;
        ssl_certificate_key /etc/letsencrypt/live/wimsbfp.tech/privkey.pem;
        ssl_session_timeout 1d;
        ssl_session_cache   shared:SSL:50m;
        ssl_session_tickets off;
        ssl_protocols        TLSv1.2 TLSv1.3;
        ssl_ciphers          ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305;
        ssl_prefer_server_ciphers off;

        # TLS 1.3 cipher suite restriction — only AES-256-GCM and ChaCha20-Poly1305.
        # ChaCha20 is preferred on mobile devices without AES-NI hardware acceleration.
        ssl_conf_command Ciphersuites TLS_AES_256_GCM_SHA384:TLS_CHACHA20_POLY1305_SHA256;

        add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
        add_header X-Content-Type-Options nosniff always;
        add_header X-Frame-Options SAMEORIGIN always;
        add_header Referrer-Policy strict-origin-when-cross-origin always;
        add_header Permissions-Policy "camera=(), microphone=(), geolocation=(self)" always;
        # Next.js emits inline bootstrap scripts for React hydration. Until the
        # app emits per-request CSP nonces, allow those scripts so the SSR
        # loading shell can hydrate and initialize authentication.
        add_header Content-Security-Policy "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; img-src 'self' data: https://*.tile.openstreetmap.org https://unpkg.com; connect-src 'self' https://*.tile.openstreetmap.org https://wimsbfp.tech; font-src 'self' https://fonts.gstatic.com; worker-src 'self' https://www.gstatic.com; frame-src 'self'; frame-ancestors 'self'" always;
        add_header Cross-Origin-Embedder-Policy "unsafe-none" always;

        # Health check — nginx handles /health directly without proxying to backend.
        # External uptime monitors (DigitalOcean Uptime, UptimeRobot) can verify the gateway
        # is reachable even if the backend is restarting.
        location = /health {
            access_log off;
            default_type application/json;
            return 200 '{"status":"ok","via":"nginx-gateway"}\n';
        }

        # Auth routes (session, callback, logout) handled by Next.js frontend
        # SSE event stream — disable buffering for real-time push
        location = /api/events/stream {
            proxy_pass http://backend_servers;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_buffering off;
            proxy_cache off;
            proxy_read_timeout 86400s;  # long-lived connection
            proxy_send_timeout 86400s;
            chunked_transfer_encoding off;
        }

        location /api/auth/ {
            proxy_pass http://frontend_servers;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_pass_request_headers on;
        }

        location /api/v1/public/ {
            limit_req  zone=public_api burst=5 nodelay;
            limit_conn addr 10;

            proxy_pass http://backend_servers;
            proxy_set_header Host $host;
            # Use the pre-real-IP-module socket address so the backend rate
            # limiter cannot be bypassed by a spoofed X-Forwarded-For header.
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $realip_remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_read_timeout 60s;
            proxy_send_timeout 60s;
            proxy_cookie_domain nginx-gateway $host;
            add_header Access-Control-Allow-Origin $cors_origin always;
            add_header Access-Control-Allow-Credentials true always;
            add_header Access-Control-Allow-Methods 'GET, POST, PUT, DELETE, OPTIONS' always;
            add_header Access-Control-Allow-Headers 'Authorization, Content-Type, Cookie' always;
            add_header Access-Control-Expose-Headers "Retry-After" always;

            if ($request_method = 'OPTIONS') {
                add_header Access-Control-Allow-Origin $cors_origin always;
                add_header Access-Control-Allow-Credentials true always;
                add_header Access-Control-Allow-Methods 'GET, POST, PUT, DELETE, OPTIONS' always;
                add_header Access-Control-Allow-Headers 'Authorization, Content-Type, Cookie' always;
                add_header Access-Control-Expose-Headers "Retry-After" always;
                add_header Content-Length 0;
                add_header Content-Type text/plain;
                return 204;
            }
        }

        location /api/civilian/ {
            limit_req  zone=civilian_api burst=10 nodelay;
            limit_conn addr 10;

            proxy_pass http://backend_servers;
            proxy_set_header Host $host;
            # Use the pre-real-IP-module socket address so the backend DB rate
            # limiter cannot be bypassed by a spoofed X-Forwarded-For header.
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $realip_remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_read_timeout 30s;
            proxy_send_timeout 30s;
            proxy_cookie_domain nginx-gateway $host;
            add_header Access-Control-Allow-Origin $cors_origin always;
            add_header Access-Control-Allow-Credentials true always;
            add_header Access-Control-Allow-Methods 'GET, POST, PUT, DELETE, OPTIONS' always;
            add_header Access-Control-Allow-Headers 'Authorization, Content-Type, Cookie' always;
            add_header Access-Control-Expose-Headers "Retry-After" always;

            if ($request_method = 'OPTIONS') {
                add_header Access-Control-Allow-Origin $cors_origin always;
                add_header Access-Control-Allow-Credentials true always;
                add_header Access-Control-Allow-Methods 'GET, POST, PUT, DELETE, OPTIONS' always;
                add_header Access-Control-Allow-Headers 'Authorization, Content-Type, Cookie' always;
                add_header Access-Control-Expose-Headers "Retry-After" always;
                add_header Content-Length 0;
                add_header Content-Type text/plain;
                return 204;
            }
        }

        location /api/ {
            limit_req  zone=general_api burst=50 nodelay;
            limit_conn addr 20;

            proxy_pass http://backend_servers;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_read_timeout 300s;
            proxy_send_timeout 300s;
            # Keep cookie Domain in sync between nginx-gateway and browser
            proxy_cookie_domain nginx-gateway $host;
            # CORS headers — backend does not add them, so nginx provides them.
            add_header Access-Control-Allow-Origin $cors_origin always;
            add_header Access-Control-Allow-Credentials true always;
            add_header Access-Control-Allow-Methods 'GET, POST, PUT, DELETE, OPTIONS' always;
            add_header Access-Control-Allow-Headers 'Authorization, Content-Type, Cookie' always;

            # Handle OPTIONS preflight directly — do not proxy to backend.
            if ($request_method = 'OPTIONS') {
                add_header Access-Control-Allow-Origin $cors_origin always;
                add_header Access-Control-Allow-Credentials true always;
                add_header Access-Control-Allow-Methods 'GET, POST, PUT, DELETE, OPTIONS' always;
                add_header Access-Control-Allow-Headers 'Authorization, Content-Type, Cookie' always;
                add_header Content-Length 0;
                add_header Content-Type text/plain;
                return 204;
            }
        }

        location = /auth/login {
            return 301 /login;
        }

        location = /auth/login/ {
            return 301 /login;
        }

        location = /report/tracking {
            return 301 /tracking$is_args$args;
        }

        location = /report/tracking/ {
            return 301 /tracking$is_args$args;
        }

        # POST-only rate limit for password reset abuse protection.
        location = /auth/realms/bfp/login-actions/reset-credentials {
            limit_req  zone=reset_credentials burst=2 nodelay;
            limit_conn addr 10;

            proxy_pass http://keycloak_servers/auth/realms/bfp/login-actions/reset-credentials;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Forwarded-Host $host;
            proxy_set_header X-Forwarded-Port $server_port;
        }

        location /auth/ {
            limit_req  zone=keycloak_api burst=20 nodelay;
            limit_conn addr 10;

            proxy_pass http://keycloak_servers/auth/;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Forwarded-Host $host;
            proxy_set_header X-Forwarded-Port $server_port;
        }

        # /metrics is an internal-only Prometheus scrape target (system
        # resource gauges, request/inference timings). Scrapers reach it
        # directly at backend:8000 over the compose network; it must never
        # be served through the public edge. Deny explicitly so a future
        # routing change can't expose it.
        location = /metrics {
            return 404;
        }

        location / {
            proxy_pass http://frontend_servers/;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
        }
    }
}

